/// The filter's error constant: E · (1 + 2u)^8 with E = 648u + 7020u^2 + 28600u^3 + 62728u^4 +
/// 85624u^5 + 79096u^6 + 52816u^7 + 27072u^8 + 11064u^9 + 3548u^10 + 824u^11 + 120u^12 + 8u^13, the
/// result's unit error (header), rounded up to an `f64`: 5699868278390801 · 2^-96.
const ERROR: f64 = f64::from_bits(0x3d34_4000_0000_0011);

/// `ellipse_side`'s sign from its `f64` filter, or `None` when the filter's bound cannot certify
/// it.
///
/// `Some(Sign::Zero)` only when the scale is zero, which makes the exact value zero; `None` also
/// for a rounded input outside its declared range.
