#[must_use]
#[allow(
    clippy::many_single_char_names,
    clippy::similar_names,
    clippy::too_many_arguments,
    reason = "names, parameters and lines follow the description: one per input and step"
)]
pub fn filter(
    x: i128,
    y: i128,
    w: i128,
    k: P2,
    mx: i128,
    my: i128,
    p: i128,
    q: i128,
) -> Option<Sign> {
    let x = rounded_f64(x, 124)?;
    let w = rounded_f64(w, 83)?;
    let k_x = exact_f64(k.x);
    let ux_1 = w * k_x;
    let ux = x - ux_1;
    let y = rounded_f64(y, 124)?;
    let k_y = exact_f64(k.y);
    let uy_1 = w * k_y;
    let uy = y - uy_1;
    let mx = rounded_f64(mx, 41)?;
    let along_1 = ux * mx;
    let my = rounded_f64(my, 41)?;
    let along_2 = uy * my;
    let along = along_1 + along_2;
    let across_1 = uy * mx;
    let across_2 = ux * my;
    let across = across_1 - across_2;
    let p = rounded_f64(p, 22)?;
    let pa = p * along;
    let q = rounded_f64(q, 22)?;
    let qa = q * across;
    let nn_1 = mx * mx;
    let nn_2 = my * my;
    let nn = nn_1 + nn_2;
    let level_1 = p * nn;
    let level = level_1 * w;
    let s_1 = pa * pa;
    let s_2 = qa * qa;
    let s_3 = s_1 + s_2;
    let s_4 = level * level;
    let s = s_3 - s_4;
    let m_x = largest_magnitude([k_x]);
    let m_y = largest_magnitude([k_y]);
    let m_a = largest_magnitude([x, y]);
    let m_w = largest_magnitude([w]);
    let m_m = largest_magnitude([mx, my]);
    let m_r = largest_magnitude([p, q]);
    let scale = larger(m_w * m_w * m_m * m_m, m_a * m_a);
    let scale = larger(scale, m_y * m_a * m_w);
    let scale = larger(scale, m_y * m_y * m_w * m_w);
    let scale = larger(scale, m_x * m_a * m_w);
    let scale = larger(scale, m_x * m_y * m_w * m_w);
    let scale = larger(scale, m_x * m_x * m_w * m_w);
    let scale = m_m * m_m * m_r * m_r * scale;
    decide(s, ERROR, scale)
}

/// `ellipse_side`'s exact value: each step in the type its certificate gives it, with checked
/// arithmetic; `None` only if a step overflowed, which the certificate rules out; `None` also for a
/// rounded input outside its declared range.
#[inline]
#[must_use]
#[allow(
    clippy::many_single_char_names,
    clippy::similar_names,
    clippy::too_many_arguments,
    reason = "names, parameters and lines follow the description: one per input and step"
)]
pub fn value(
    x: i128,
    y: i128,
    w: i128,
    k: P2,
    mx: i128,
    my: i128,
    p: i128,
    q: i128,
) -> Option<I384> {
    let x = within(x, 124)?;
    let w = within(w, 83)?;
    let k_x = k.x.get();
    let ux_1 = w.checked_mul(i128::from(k_x))?;
    let ux = x.checked_sub(ux_1)?;
    let y = within(y, 124)?;
    let k_y = k.y.get();
    let uy_1 = w.checked_mul(i128::from(k_y))?;
    let uy = y.checked_sub(uy_1)?;
    let mx = i64::try_from(within(mx, 41)?).ok()?;
    let along_1 = I256::product_i128(ux, i128::from(mx))?;
    let my = i64::try_from(within(my, 41)?).ok()?;
    let along_2 = I256::product_i128(uy, i128::from(my))?;
    let along = along_1.checked_add(&along_2)?;
    let across_1 = I256::product_i128(uy, i128::from(mx))?;
    let across_2 = I256::product_i128(ux, i128::from(my))?;
    let across = across_1.checked_sub(&across_2)?;
    let p = i64::try_from(within(p, 22)?).ok()?;
    let pa = along.checked_mul_i128(i128::from(p))?;
    let q = i64::try_from(within(q, 22)?).ok()?;
    let qa = across.checked_mul_i128(i128::from(q))?;
    let nn_1 = i128::from(mx).checked_mul(i128::from(mx))?;
    let nn_2 = i128::from(my).checked_mul(i128::from(my))?;
    let nn = nn_1.checked_add(nn_2)?;
    let level_1 = i128::from(p).checked_mul(nn)?;
    let level = I256::product_i128(level_1, w)?;
    let s_1 = pa.resize::<6>()?.checked_mul(&pa.resize::<6>()?)?;
    let s_2 = qa.resize::<6>()?.checked_mul(&qa.resize::<6>()?)?;
    let s_3 = s_1.checked_add(&s_2)?;
    let s_4 = level.resize::<6>()?.checked_mul(&level.resize::<6>()?)?;
    let s = s_3.checked_sub(&s_4)?;
    Some(s)
}

